import sys
from math import comb

def minimize_max_stones(N, M, K):
    total_cells = (N - 1) * (M - 1)
    if K <= total_cells:
        return 1
    else:
        max_possible = K
        min_S = max_possible
        for i in range(1, N):
            for j in range(1, M):
                cnt = comb(i + j - 2, i - 1)
                if cnt == 0:
                    continue
                if K % cnt == 0:
